import { isArraysEqualDeeply } from "./isArraysEqualDeeply";
import { isArraysEqualShallow } from "./isArraysEqualShallow";
import { isBothArraysShallow } from "./isBothArraysShallow";
import { isObjectNested } from "./isObjectNested";
import { isObjectsEqualShallow } from "./isObjectsEqualShallow";
import { isPrimitive } from "./isPrimitive";
export const isBothObjects = (elem1, elem2) => typeof elem1 === "object" && typeof elem2 === "object" && elem1 !== null && elem2 !== null;
export const isBothArrays = (elem1, elem2) => Array.isArray(elem1) && Array.isArray(elem2);
export const isBothFunctions = (elem1, elem2) => typeof elem1 === "function" && typeof elem2 === "function";
export const isBothObjectsShallow = (elem1, elem2) => !isObjectNested(elem1) && !isObjectNested(elem2);
export const isArraysNotEqual = (val1, val2) => {
    if (!isBothArrays(val1, val2)) {
        return false;
    }
    if (isBothArraysShallow(val1, val2) && !isArraysEqualShallow(val1, val2)) {
        return true;
    }
    if (!isArraysEqualDeeply(val1, val2)) {
        return true;
    }
    return false;
};
export const isPrimitivesNotEqual = (item1, item2) => isPrimitive(item1) && isPrimitive(item2) && item1 !== item2;
export const isObjectsNotEqualShallow = (val1, val2) => {
    if (!isBothObjects(val1, val2)) {
        return false;
    }
    if (isBothObjectsShallow(val1, val2) && !isObjectsEqualShallow(val1, val2)) {
        return true;
    }
    return false;
};
export const isPropertiesEqual = (elem1, elem2) => {
    const elem1Keys = Object.keys(elem1);
    for (const key of elem1Keys) {
        if (isPrimitivesNotEqual(elem1[key], elem2[key])) {
            return false;
        }
        if (isArraysNotEqual(elem1[key], elem2[key])) {
            return false;
        }
        if (isObjectsNotEqualShallow(elem1[key], elem2[key])) {
            return false;
        }
        // eslint-disable-next-line @typescript-eslint/no-use-before-define
        if (!isElementsEqual(elem1[key], elem2[key])) {
            return false;
        }
    }
    return true;
};
export function isElementsEqual(...args) {
    const elem1 = args[0];
    const elem2 = args[1];
    // compare dates
    if (elem1 instanceof Date && elem2 instanceof Date) {
        return elem1.getTime() === elem2.getTime();
    }
    // compare primitives
    if (isPrimitive(elem1) && isPrimitive(elem2)) {
        return elem1 === elem2;
    }
    // is the same function
    if (isBothFunctions(elem1, elem2)) {
        return elem1.toString() === elem2.toString();
    }
    // check {} and [] case
    if (Array.isArray(elem1) !== Array.isArray(elem2)) {
        return false;
    }
    // check 'function' and 'object' case
    if (typeof elem1 !== typeof elem2) {
        return false;
    }
    // is the same object
    if (elem1 === elem2) {
        return true;
    }
    if (isBothArraysShallow(elem1, elem2)) {
        return isArraysEqualShallow(elem1, elem2);
    }
    if (isBothObjectsShallow(elem1, elem2)) {
        return isObjectsEqualShallow(elem1, elem2);
    }
    return isPropertiesEqual(elem1, elem2);
}
